# Generated by Phase: IMPLEMENT | Feature: EVOL-106
"""Proof at the close (EVOL-106): `gate.py proof` — each case proven by its run, each scenario traced to its evidence.

config      `config/quality.json → proof`: `tool` — the answered end-to-end tool (SETUP Q23.8 `testing.e2e_tool`):
            `playwright` (the built-in reader of its JSON reporter, the only Playwright report that carries steps),
            `none` (no end-to-end layer: every case is proven by the seal or by hand), or another tool whose adapter the
            materialisation built — its `convert` command (`{report}` is the native report's path) prints the proof
            shape on stdout. `helper` / `canary` — the adapter's clause helper and canary spec (Playwright:
            `tests/e2e/support/clauses.ts`, `tests/e2e/specs/canary.spec.ts`). `e2e_roots` — the test roots of the
            end-to-end layer (default `e2e/**`, `tests/e2e/**`).
shape       {tests: [{title, status, steps: [{title, error}], annotations: [{type, description}]}]} — the one shape
            judged, whatever the tool. A test titled `[F/C]` proves case F/C.
clauses     a test-plan row with a `Gherkin Ref` takes the steps of the `spec.feature` scenario it names (the
            Background, then the scenario, each line verbatim; And/But take the keyword before them; a Scenario Outline
            `<x>` matches any text); any other row has one Then: its first column whose header starts with `Expected`.
green run   red per test: its steps are not the case's clauses in order (one step per clause, `<Keyword> <text>`, after
            whitespace and markdown are normalised); a Then step has no `asserted` annotation naming it; it did not pass.
control run red per test: no `control` annotation (the control did not act); it passed; it failed first on a step that is
            not a Then. A case is proven when every test that names it holds in both runs.
canary      every suite carries `canary: green`, `canary: order` (its steps out of order) and `canary: unasserted` (a
            Then with no assertion), on the fixed clauses below. A run whose canary verdicts differ from the expected
            ones is refused — the adapter is broken, not the cases; a converter that marks every Then asserted is caught.
--record    reads both runs and writes `docs/spec/{F}/qa/proof.json` per feature (sha, env, at, cases); refused when
            `qa --ready --env E` is red or the canary disagrees. History lives in git.
--report    the same judgment, written nowhere — the end-to-end worker's local check.
--trace F   scenario → AC row → test → evidence: red for a scenario with no AC row, a Gherkin Ref naming no scenario, a
            case with no linking test (a baselined one included), a test with no evidence — absent from or red in
            proof.json (end-to-end), the loop's seal not valid at the proof's SHA (unit and integration). Manual: manual.
--check     (light member, full-sdlc) the adapter is in place: a tool other than `none` has its helper and its canary
            spec, the spec carrying the three canary titles; a tool other than Playwright also has an executable `convert`.
"""
from __future__ import annotations

import datetime as _dt
import json
import os
import re
import shlex
import shutil
import subprocess
from pathlib import Path

from . import documents
from .common import GateFault, glob_match, key

CANARY_CLAUSES = [("Given", "the canary page is open"), ("When", "the canary acts"), ("Then", "the canary shows its result")]
CANARY = {"canary: green": set(), "canary: order": {"order"}, "canary: unasserted": {"asserted"}}
PLAYWRIGHT = {"helper": "tests/e2e/support/clauses.ts", "canary": "tests/e2e/specs/canary.spec.ts"}
TAG = re.compile(r"^\s*\[(?P<id>[^\]\n]+)\]")
STEP = re.compile(r"^(Given|When|Then|And|But|\*)\s+(.*)$")
BLOCK = re.compile(r"^(Background|Scenario Outline|Scenario Template|Scenario|Example)\s*:\s*(.*)$")
CONVERT_TIMEOUT = 300
SCRIPT_SUFFIXES = (".py", ".js", ".mjs", ".cjs", ".ts", ".sh", ".rb", ".pl", ".ps1")


# ─── config ─────────────────────────────────────────────────────────────────────

def cfg(repo: Path) -> dict:
    p = key(repo, "proof", default=None)
    if not isinstance(p, dict) or not str(p.get("tool") or "").strip():
        raise GateFault("`proof.tool` is missing from config/quality.json — the end-to-end tool is a project answer "
                        "(SETUP Q23.8 testing.e2e_tool); SETUP --upgrade asks it")
    tool = str(p["tool"]).strip().lower()
    conv = p.get("convert")
    if tool not in ("playwright", "none") and not (isinstance(conv, str) and "{report}" in conv):
        raise GateFault(f"`proof.tool` is {tool!r} and `proof.convert` names no command with `{{report}}` — the "
                        "materialisation builds that converter for any tool besides Playwright (SETUP --upgrade)")
    roots = p.get("e2e_roots", ["e2e/**", "tests/e2e/**"])
    if not isinstance(roots, list) or not roots or not all(isinstance(x, str) for x in roots):
        raise GateFault("proof.e2e_roots must be a non-empty list of globs")
    if tool == "none":
        roots = []   # no end-to-end layer: a test under tests/e2e/ is proven by the seal, never owed a run
    defaults = PLAYWRIGHT if tool == "playwright" else {}
    adapter = {k: str(p.get(k) or defaults.get(k) or "") for k in ("helper", "canary")}
    if tool != "none" and not all(adapter.values()):
        raise GateFault(f"`proof.helper` and `proof.canary` must name the {tool} adapter's clause helper and canary spec — the materialisation writes both")
    return {"tool": tool, "convert": conv if tool not in ("playwright", "none") else None, "roots": roots, **adapter}


# ─── clauses ────────────────────────────────────────────────────────────────────

def norm(s: str) -> str:
    return re.sub(r"\s+", " ", re.sub(r"[*`_]", "", str(s))).strip().casefold()


def scenarios(text: str) -> dict[str, dict]:
    """normalised Scenario title → {title, steps: [(Keyword, text)], outline} — the Background's steps first."""
    out: dict[str, dict] = {}
    bg: list[tuple[str, str]] = []
    cur, in_bg, last = None, False, "Given"
    for raw in text.splitlines():
        s = raw.strip()
        m = BLOCK.match(s)
        if m:
            last, in_bg = "Given", m.group(1) == "Background"
            cur = None if in_bg else norm(m.group(2))
            if cur is not None:
                out[cur] = {"title": m.group(2).strip(), "steps": list(bg), "outline": m.group(1) != "Scenario" and m.group(1) != "Example"}
            continue
        if re.match(r"^(Feature|Rule|Examples|Scenarios)\s*:", s):
            cur, in_bg = None, False
            continue
        m = STEP.match(s)
        if not m:
            continue
        kw = last if m.group(1) in ("And", "But", "*") else m.group(1)
        last = kw
        if in_bg:
            bg.append((kw, m.group(2).strip()))
        elif cur is not None:
            out[cur]["steps"].append((kw, m.group(2).strip()))
    return out


def _feature_scenarios(repo: Path, feature: str) -> dict[str, dict]:
    p = repo / "docs" / "spec" / feature / "spec.feature"
    return scenarios(p.read_text(encoding="utf-8", errors="replace")) if p.is_file() else {}


def clauses_of(row: dict, scen: dict[str, dict]) -> tuple[list[tuple[str, str]] | None, str]:
    """(clauses, problem) for one declared row's cells — None with the reason when the row names no clause."""
    cells = row.get("cells") or {}
    ref = str(cells.get("GHERKIN REF") or "").strip()
    if ref:
        sc = scen.get(norm(ref))
        if sc is None:
            return None, f"its Gherkin Ref `{ref}` names no scenario of spec.feature"
        if not any(k == "Then" for k, _ in sc["steps"]):
            return None, f"its scenario `{ref}` has no Then — a case with nothing to assert proves nothing"
        return sc["steps"], ""
    exp = next((v for h, v in cells.items() if h.startswith("EXPECTED") and str(v).strip()), "")
    if not exp:
        return None, "the row has no Gherkin Ref and no Expected column — it states no clause to prove"
    return [("Then", exp)], ""


def _fits(kw: str, text: str, got: str) -> bool:
    """`got` is the clause: its literal parts in order, each Outline `<x>` one character or more. No regex: a title
    the writer controls never backtracks — the leftmost place of each part leaves the most room for the rest."""
    parts = re.split(r"<[^>\n]+>", norm(f"{kw} {text}"))
    if len(parts) == 1:
        return got == parts[0]
    head, *mid, tail = parts
    if not got.startswith(head) or not got.endswith(tail):
        return False
    pos, end = len(head), len(got) - len(tail)
    for p in mid:
        i = got.find(p, pos + 1, end)
        if i < 0:
            return False
        pos = i + len(p)
    return end - pos >= 1


# ─── the shape: Playwright's JSON reporter, or the built converter ─────────────

def _objs(node: dict, key: str) -> list[dict]:
    """`node[key]` as a list of objects; absent is empty; anything else is no Playwright report."""
    v = node.get(key)
    if v is None:
        return []
    if not isinstance(v, list) or not all(isinstance(x, dict) for x in v):
        raise GateFault(f"`{key}` is not a list of objects — not a Playwright JSON report")
    return v


def from_playwright(doc) -> dict:
    if not isinstance(doc, dict):
        raise GateFault("the report's root is not an object — not a Playwright JSON report")
    tests: list[dict] = []

    def walk(suite: dict) -> None:
        for s in _objs(suite, "suites"):
            walk(s)
        for spec in _objs(suite, "specs"):
            for t in _objs(spec, "tests"):
                res = _objs(t, "results")
                lastr = res[-1] if res else {}
                ann = []   # the test's and the result's annotations — the same mark may sit in both
                for a in _objs(t, "annotations") + _objs(lastr, "annotations"):
                    if a not in ann:
                        ann.append(a)
                tests.append({"title": str(spec.get("title") or ""), "status": str(lastr.get("status") or "skipped"),
                              "steps": [{"title": str(st.get("title") or ""), "error": bool(st.get("error"))} for st in _objs(lastr, "steps")],
                              "annotations": ann})
    for s in _objs(doc, "suites"):
        walk(s)
    return {"tests": tests}


def _shape(doc) -> dict:
    ok = isinstance(doc, dict) and isinstance(doc.get("tests"), list) and all(
        isinstance(t, dict) and isinstance(t.get("title"), str) and isinstance(t.get("status"), str)
        and isinstance(t.get("steps"), list) and isinstance(t.get("annotations"), list)
        and all(isinstance(s, dict) and isinstance(s.get("title"), str) for s in t["steps"]) for t in doc["tests"])
    if not ok:
        raise GateFault("the report is not the proof shape {tests: [{title, status, steps, annotations}]} — the adapter is broken")
    return doc


def load(repo: Path, c: dict, report: str) -> dict:
    p = Path(report) if Path(report).is_absolute() else repo / report
    if not p.is_file():
        raise GateFault(f"the report {report} does not exist — run the suite with its JSON reporter first")
    if c["tool"] == "playwright":
        try:
            return _shape(from_playwright(json.loads(p.read_text(encoding="utf-8"))))
        except (ValueError, RecursionError) as e:
            raise GateFault(f"the report {report} is not readable JSON ({e.__class__.__name__})") from None
    argv = [a.replace("{report}", str(p)) for a in _argv(c["convert"])]
    try:
        r = subprocess.run(argv, cwd=str(repo), capture_output=True, text=True, timeout=CONVERT_TIMEOUT)
    except (OSError, subprocess.TimeoutExpired) as e:
        raise GateFault(f"the converter `{argv[0]}` could not run ({e.__class__.__name__}) — the adapter is broken") from None
    if r.returncode != 0:
        raise GateFault(f"the converter exited {r.returncode}: {(r.stderr.strip().splitlines() or ['(no message)'])[-1][:200]}")
    try:
        return _shape(json.loads(r.stdout))
    except (ValueError, RecursionError):
        raise GateFault("the converter printed no JSON — the adapter is broken") from None


def _argv(cmd: str) -> list[str]:
    try:
        argv = shlex.split(cmd)
    except ValueError:
        raise GateFault("proof.convert is not one command line (an unbalanced quote) — the adapter is broken") from None
    if not argv:
        raise GateFault("proof.convert names no command — the adapter is broken")
    return argv


# ─── the judgment ───────────────────────────────────────────────────────────────

def _ann(t: dict, kind: str) -> set[str]:
    return {norm(a.get("description") or "") for a in t["annotations"] if isinstance(a, dict) and a.get("type") == kind}


def judge_green(t: dict, want: list[tuple[str, str]]) -> list[tuple[str, str]]:
    """(kind, problem) for one test of the green run against its clauses."""
    got = [norm(s["title"]) for s in t["steps"]]
    out = []
    if len(got) != len(want) or not all(_fits(k, x, g) for (k, x), g in zip(want, got)):
        out.append(("order", "its steps are not the case's clauses in order — want [" + "; ".join(f"{k} {x}" for k, x in want)
                    + "], got [" + "; ".join(s["title"] for s in t["steps"]) + "]"))
    asserted = _ann(t, "asserted")
    for g in got:
        if g.startswith("then ") and g not in asserted:
            out.append(("asserted", f"its step `{g}` has no `asserted` annotation — a Then that asserts nothing proves nothing"))
    if t["status"] != "passed":
        out.append(("status", f"it did not pass ({t['status']})"))
    return out


def judge_control(t: dict) -> list[tuple[str, str]]:
    if not any(isinstance(a, dict) and a.get("type") == "control" for a in t["annotations"]):
        return [("control", "the control run carries no `control` annotation — the control did not act (CASE_CONTROL=1)")]
    if t["status"] == "passed":
        return [("control", "it passed with its decisive response corrupted — its Then proves nothing")]
    first = next((s for s in t["steps"] if s.get("error")), None)
    if first is None or not norm(first["title"]).startswith("then "):
        return [("control", f"under the control it failed first on `{first['title'] if first else '(outside its steps)'}` — not a Then")]
    return []


def canary(green: dict, control: dict | None) -> list[str]:
    """The adapter's own proof: every canary present, each with its expected verdict (the control run's part only
    when a control run is given)."""
    out = []
    by = {norm(t["title"]): t for t in green["tests"]}
    for title, want in CANARY.items():
        t = by.get(title)
        if t is None:
            out.append(f"`{title}` is absent from the green run — the suite carries the adapter canary")
            continue
        kinds = {k for k, _ in judge_green(t, CANARY_CLAUSES)}
        if kinds != want:
            out.append(f"`{title}` judged {sorted(kinds) or 'green'}, expected {sorted(want) or 'green'} — the adapter is broken")
    if control is None:
        return out
    ctl = next((t for t in control["tests"] if norm(t["title"]) == "canary: green"), None)
    if ctl is None:
        out.append("`canary: green` is absent from the control run")
    elif judge_control(ctl):
        out.append("`canary: green` under the control: " + judge_control(ctl)[0][1] + " — the adapter is broken")
    return out


def judge(repo: Path, green: dict, control: dict | None) -> dict:
    """qualified case → {ok, problems, tests}, and findings for tests that name no declared case."""
    from . import traceability as tr
    c = tr.cfg(repo)
    dec, _ = tr.declared(repo, c) if c["required"] else ({}, [])
    ctl = {}
    for t in (control or {}).get("tests", []):
        m = TAG.match(t["title"])
        if m:
            ctl.setdefault(m.group("id").strip(), []).append(t)
    cases: dict[str, dict] = {}
    unknown, scen = [], {}
    for t in green["tests"]:
        m = TAG.match(t["title"])
        if not m:
            continue
        qid = m.group("id").strip()
        if qid not in dec:
            unknown.append(f"`{t['title']}` names no declared case")
            continue
        feat = qid.split("/")[0]
        scen.setdefault(feat, _feature_scenarios(repo, feat))
        want, why = clauses_of(dec[qid], scen[feat])
        probs = [why] if want is None else [p for _, p in judge_green(t, want)]
        if control is not None:
            mine = ctl.get(qid) or []
            probs += [p for x in mine for _, p in judge_control(x)] or ([] if mine else ["absent from the control run"])
        e = cases.setdefault(qid, {"ok": True, "problems": [], "tests": 0})
        e["tests"] += 1
        e["problems"] += probs
        e["ok"] = not e["problems"]
    return {"cases": cases, "unknown": unknown}


def _head(repo: Path) -> str:
    r = subprocess.run(["git", "-C", str(repo), "rev-parse", "HEAD"], capture_output=True, text=True, timeout=60)
    if r.returncode != 0:
        raise GateFault("git rev-parse HEAD failed — the proof names the SHA it ran on")
    return r.stdout.strip()


def report(repo: Path, green: str, control: str | None = None) -> dict:
    c = cfg(repo)
    if c["tool"] == "none":
        return {"ok": True, "na": True, "entries": [], "reason": "proof.tool is none — no end-to-end layer to judge"}
    g = load(repo, c, green)
    k = load(repo, c, control) if control else None
    return _verdict(judge(repo, g, k), canary(g, k))


def _verdict(j: dict, can: list[str]) -> dict:
    rows = [{"id": "canary", "ok": not can, "problems": can, "note": "the adapter judges its planted cases as expected"}]
    rows += [{"id": q, "ok": e["ok"], "problems": e["problems"], "note": f"{e['tests']} test(s) proven"} for q, e in sorted(j["cases"].items())]
    if j["unknown"]:
        rows.append({"id": "unknown", "ok": False, "problems": j["unknown"], "note": ""})
    red = [r for r in rows if not r["ok"]]
    return {"ok": not red, "entries": rows, "cases": j["cases"], "canary": can,
            "reason": f"{len(red)} of {len(rows)} red" if red else f"{len(j['cases'])} case(s) proven by their run"}


def record(repo: Path, green: str, control: str, env: str, now: _dt.datetime | None = None) -> dict:
    from . import qa
    c = cfg(repo)
    if c["tool"] == "none":
        raise GateFault("proof.tool is none — there is no end-to-end run to record")
    r = qa.ready(repo, env)
    if not r["ok"]:
        return {"ok": False, "refused": True, "entries": r.get("entries", []), "reason": f"refused — {env} is not ready: {r['reason']}"}
    g, k = load(repo, c, green), load(repo, c, control)
    can = canary(g, k)
    if can:
        return {"ok": False, "refused": True, "entries": [{"id": "canary", "ok": False, "problems": can, "note": ""}],
                "reason": "refused — the adapter canary disagrees: the adapter is broken, not the cases"}
    res = _verdict(judge(repo, g, k), [])
    sha, at = _head(repo), (now or _dt.datetime.now(_dt.timezone.utc)).strftime("%Y-%m-%dT%H:%M:%SZ")
    written = []
    for feat in sorted({q.split("/")[0] for q in res["cases"]}):
        p = repo / "docs" / "spec" / feat / "qa" / "proof.json"
        p.parent.mkdir(parents=True, exist_ok=True)
        body = {"sha": sha, "env": env, "at": at,
                "cases": {q: {"ok": e["ok"], "problems": e["problems"]} for q, e in sorted(res["cases"].items()) if q.split("/")[0] == feat}}
        p.write_text(json.dumps(body, indent=2) + "\n", encoding="utf-8")
        written.append(str(p.relative_to(repo)))
    return {**res, "written": written}


# ─── the trace ──────────────────────────────────────────────────────────────────

def _proof(repo: Path, feature: str) -> dict | None:
    p = repo / "docs" / "spec" / feature / "qa" / "proof.json"
    if not p.is_file():
        return None
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except (ValueError, RecursionError):
        raise GateFault(f"{p.relative_to(repo)} is not JSON — re-record the proof") from None
    return d if isinstance(d, dict) and isinstance(d.get("cases"), dict) else None


def _stale(repo: Path, pr: dict, roots: list[str]) -> str:
    """Why proof.json no longer speaks for HEAD — '' when its SHA is HEAD, or an ancestor whose diff to HEAD moves
    neither the runtime surface nor an end-to-end test (the reached rule of `qa --ready`, applied to the run)."""
    from . import delivery, runtime
    sha = pr.get("sha")
    if not isinstance(sha, str) or not delivery.SHA_RE.fullmatch(sha):
        return "proof.json names no commit SHA — re-record the run (gate.py proof --record)"
    if sha == _head(repo):
        return ""
    if subprocess.run(["git", "-C", str(repo), "merge-base", "--is-ancestor", sha, "HEAD"], capture_output=True, timeout=60).returncode != 0:
        return f"proof.json ran on {sha[:8]}, which is not this branch's build — re-record the run"
    moved = runtime.changed(repo, sha)
    if moved["touched"]:
        return f"HEAD moved the runtime surface since the proof ({sha[:8]}): {moved['reason']} — redeploy and re-record"
    r = subprocess.run(["git", "-C", str(repo), "diff", "--name-only", "--no-renames", f"{sha}..HEAD"], capture_output=True, text=True, timeout=60)
    if r.returncode != 0:
        raise GateFault(f"git diff {sha[:8]}..HEAD failed — the trace cannot tell whether the proof is current")
    tests = [x for x in r.stdout.splitlines() if x and any(glob_match(x, g) for g in roots)]
    return f"{len(tests)} end-to-end test file(s) changed since the proof ({sha[:8]}), e.g. {tests[0]} — re-record the run" if tests else ""


def trace(repo: Path, feature: str, control_point: str = "push") -> dict:
    from . import seal
    from . import traceability as tr
    if not tr.FEATURE.fullmatch(feature):
        raise GateFault(f"`{feature}` is not a feature id (the plan folder under docs/spec/, e.g. FEAT-001)")
    c = tr.cfg(repo)
    if not c["required"]:
        return {"ok": True, "na": True, "entries": [], "trace": [], "reason": f"traceability is not required here ({c['reason']})"}
    if not documents.exists(repo, f"docs/spec/{feature}/test_plan.md"):   # a file or its pin (EVOL-080)
        return {"ok": False, "entries": [], "trace": [], "reason": f"docs/spec/{feature}/test_plan.md is absent — no case to trace (a typo is never green)"}
    try:
        pc = cfg(repo)
    except GateFault:
        pc = {"tool": "none", "roots": []}
    listing = tr.files(repo)
    dec, _ = tr.declared(repo, c, listing)
    lnk, _ = tr.links(repo, c, listing)
    mine = {q: d for q, d in dec.items() if q.split("/")[0] == feature}
    scen = _feature_scenarios(repo, feature)
    pr = _proof(repo, feature)
    stale = _stale(repo, pr, pc["roots"]) if pr else ""
    sealed = seal.check(repo, ref=pr["sha"] if pr and not stale else "HEAD", control_point=control_point)
    refs = {norm((d.get("cells") or {}).get("GHERKIN REF") or ""): q for q, d in mine.items() if (d.get("cells") or {}).get("GHERKIN REF")}
    rows = [{"id": f"scenario `{s['title']}`", "ok": False, "note": "", "problems": ["no AC row names it in Gherkin Ref"]}
            for k, s in sorted(scen.items()) if k not in refs]
    out = []
    for q, d in sorted(mine.items()):
        out.append(_trace_case(q, d, scen, lnk, pc, pr, sealed, stale))
        rows.append({"id": q, "ok": out[-1]["ok"], "note": out[-1]["evidence"] or "", "problems": out[-1]["problems"]})
    red = [r for r in rows if not r["ok"]]
    return {"ok": not red, "entries": rows, "trace": out, "proof_sha": (pr or {}).get("sha"),
            "reason": f"{len(red)} of {len(rows)} red" if red else f"{len(out)} case(s) traced to their evidence"}


def _trace_case(q: str, d: dict, scen: dict, lnk: dict, pc: dict, pr: dict | None, sealed: dict, stale: str = "") -> dict:
    ref = str((d.get("cells") or {}).get("GHERKIN REF") or "").strip()
    probs = [f"its Gherkin Ref `{ref}` names no scenario"] if ref and norm(ref) not in scen else []
    if d["manual"]:
        return {"case": q, "scenario": ref or None, "tests": [], "layer": "manual", "evidence": "manual", "ok": not probs, "problems": probs}
    tests = lnk.get(q, [])
    if not tests:
        return {"case": q, "scenario": ref or None, "tests": [], "layer": None, "evidence": None, "ok": False,
                "problems": probs + ["no test links it (a baselined case is not proven)"]}
    e2e = any(glob_match(t.rsplit(":", 1)[0], r) for t in tests for r in pc["roots"])
    if e2e:
        ent = ((pr or {}).get("cases") or {}).get(q)
        ev = "proof" if ent and ent.get("ok") and not stale else None
        if ev is None:
            probs.append(stale if ent and ent.get("ok") else "absent from proof.json — record the run (gate.py proof --record)" if not ent
                         else "red in proof.json: " + "; ".join(str(x) for x in ent.get("problems") or []))
    else:
        ev = "seal" if sealed.get("ok") else None
        if ev is None:
            probs.append(f"the loop's seal is not valid at the proof's SHA — {sealed.get('reason')}")
    return {"case": q, "scenario": ref or None, "tests": tests, "layer": "e2e" if e2e else "unit", "evidence": ev, "ok": not probs, "problems": probs}


# ─── the adapter in place ───────────────────────────────────────────────────────

def check(repo: Path) -> dict:
    from . import data
    if data.answers(repo).get("project_tracking.feature_phases") != "full-sdlc":
        return {"ok": True, "na": True, "entries": [], "reason": "the feature preset is not full-sdlc — no proof at the close"}
    try:
        c = cfg(repo)
    except GateFault as e:
        return {"ok": False, "entries": [], "reason": str(e)}
    if c["tool"] == "none":
        return {"ok": True, "na": True, "entries": [], "reason": "proof.tool is none — no end-to-end layer"}
    probs = [f"the {what} {c[k]} is absent — the materialisation writes it ({c['tool']} adapter)"
             for k, what in (("helper", "clause helper"), ("canary", "adapter canary spec")) if not (repo / c[k]).is_file()]
    if (repo / c["canary"]).is_file():
        text = (repo / c["canary"]).read_text(encoding="utf-8", errors="replace")
        probs += [f"the canary spec {c['canary']} carries no `{t}` test" for t in CANARY if t not in text]
    if c["convert"]:
        try:
            argv = _argv(c["convert"])
        except GateFault as e:
            return {"ok": False, "entries": [{"id": "adapter", "ok": False, "problems": [str(e)], "note": ""}], "reason": str(e)}
        exe, local = argv[0], repo / argv[0]
        if "/" in exe:   # a path: the file itself runs
            if exe.startswith("/") or ".." in exe.split("/"):
                probs.append(f"proof.convert names `{exe}`, outside the repository — the converter is a repository file")
            elif not local.is_file():
                probs.append(f"proof.convert names `{exe}`, which is not a file in the repository")
            elif not os.access(local, os.X_OK):
                probs.append(f"proof.convert names `{exe}`, which is not executable")
        elif not shutil.which(exe):   # a bare name is looked up on PATH, never in the repository
            probs.append(f"proof.convert names `{exe}`, which is not on PATH" + (f" — a repository file runs as `./{exe}`" if local.is_file() else ""))
        probs += [f"proof.convert names `{x}`, which is not a file in the repository — the converter the materialisation built"
                  for x in argv[1:] if "{report}" not in x and x.endswith(SCRIPT_SUFFIXES) and not (repo / x).is_file()]
    rows = [{"id": "adapter", "ok": not probs, "problems": probs, "note": f"{c['tool']}: helper, canary" + (", converter" if c["convert"] else "")}]
    return {"ok": not probs, "entries": rows, "reason": f"the {c['tool']} adapter is in place" if not probs else f"the {c['tool']} adapter is incomplete"}


def render(res: dict, name: str = "proof") -> str:
    from .delivery import render as _render
    return _render(res, name)
